G=load()

def transform(g):
    h=len(g); w=len(g[0])
    out=[row[:] for row in g]
    # horizontal rows: rows with >=2 nonzero cells
    hrows=[r for r in range(h) if sum(1 for x in g[r] if x)>=2]
    for r in hrows:
        nz=[c for c in range(w) if g[r][c]]
        lo,hi=min(nz),max(nz)
        for c in range(lo+1,hi):
            if out[r][c]==0:
                out[r][c]=g[r][c-1] or g[r][c+1]
    # vertical seeds: nonzero cells not in horizontal rows
    for c in range(w):
        col=[r for r in range(h) if out[r][c] and r not in hrows]
        if not col: continue
        top=min(col); cur=out[top][c]
        for r in range(top,-1,-1):
            if r in hrows:
                if out[r][c]: cur=out[r][c]
            out[r][c]=cur
    return out

